-- Projet Services Web - Application de messagerie
-- 5 utilisateurs, 10 contacts, 20 messages reçus et 10 envoyés par utilisateur
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DROP DATABASE IF EXISTS messagerie_web;
CREATE DATABASE messagerie_web CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE messagerie_web;

CREATE TABLE utilisateurs (
  id_utilisateur BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  courriel VARCHAR(190) NOT NULL UNIQUE,
  mot_de_passe_hash VARCHAR(255) NOT NULL,
  nom VARCHAR(80) NOT NULL,
  prenom VARCHAR(80) NOT NULL,
  photo_profil VARCHAR(255) NULL,
  telephone VARCHAR(30) NULL,
  cree_le DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  modifie_le DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE contacts (
  id_contact BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  id_utilisateur BIGINT UNSIGNED NOT NULL,
  nom VARCHAR(80) NOT NULL, prenom VARCHAR(80) NOT NULL,
  courriel VARCHAR(190) NOT NULL, photo_profil VARCHAR(255) NULL,
  telephone_mobile VARCHAR(30) NULL, telephone_fixe VARCHAR(30) NULL, telephone_pro VARCHAR(30) NULL,
  cree_le DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_contact_utilisateur FOREIGN KEY (id_utilisateur) REFERENCES utilisateurs(id_utilisateur) ON DELETE CASCADE,
  UNIQUE KEY uk_contact_courriel (id_utilisateur, courriel)
) ENGINE=InnoDB;

CREATE TABLE dossiers (
  id_dossier BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  id_utilisateur BIGINT UNSIGNED NOT NULL, nom VARCHAR(80) NOT NULL,
  type ENUM('systeme','personnel') NOT NULL DEFAULT 'personnel',
  cree_le DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_dossier_utilisateur FOREIGN KEY (id_utilisateur) REFERENCES utilisateurs(id_utilisateur) ON DELETE CASCADE,
  UNIQUE KEY uk_dossier_nom (id_utilisateur, nom)
) ENGINE=InnoDB;

CREATE TABLE messages (
  id_message BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  id_utilisateur BIGINT UNSIGNED NOT NULL, id_dossier BIGINT UNSIGNED NULL,
  expediteur_courriel VARCHAR(190) NOT NULL, destinataire_courriel VARCHAR(190) NOT NULL,
  objet VARCHAR(255) NOT NULL, contenu TEXT NOT NULL,
  direction ENUM('recu','envoye') NOT NULL, etat ENUM('envoye','recu','lu') NOT NULL,
  envoye_le DATETIME NOT NULL,
  CONSTRAINT fk_message_utilisateur FOREIGN KEY (id_utilisateur) REFERENCES utilisateurs(id_utilisateur) ON DELETE CASCADE,
  CONSTRAINT fk_message_dossier FOREIGN KEY (id_dossier) REFERENCES dossiers(id_dossier) ON DELETE SET NULL,
  INDEX idx_message_boite (id_utilisateur, direction, envoye_le), INDEX idx_message_etat (id_utilisateur, etat)
) ENGINE=InnoDB;

CREATE TABLE pieces_jointes (
  id_piece BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, id_message BIGINT UNSIGNED NOT NULL,
  nom_fichier VARCHAR(255) NOT NULL, type_mime VARCHAR(120) NOT NULL, taille_octets BIGINT UNSIGNED NOT NULL,
  chemin_stockage VARCHAR(500) NOT NULL,
  CONSTRAINT fk_piece_message FOREIGN KEY (id_message) REFERENCES messages(id_message) ON DELETE CASCADE
) ENGINE=InnoDB;





SET FOREIGN_KEY_CHECKS = 1;

-- Contrôle attendu : 5 utilisateurs, 50 contacts, 100 reçus, 50 envoyés
SELECT COUNT(*) AS utilisateurs FROM utilisateurs;
SELECT COUNT(*) AS contacts FROM contacts;
SELECT direction, COUNT(*) AS total FROM messages GROUP BY direction;
SELECT id_utilisateur, SUM(direction='recu') AS recus, SUM(direction='envoye') AS envoyes FROM messages GROUP BY id_utilisateur;